pa:check () 
{ 
    { 
        echo "${FUNCNAME[1]} ";
        if pa:cmpaa opts ropts && pa:cmpa args rargs && pa:cmpa cont rcont; then
            echo OK;
            declare -p test;
        else
            echo KO;
            declare -p test opts ropts args rargs cont rcont;
        fi
    } | tr -d '\n' | sed 's/declare -[aA]//g';
    echo
}
pa:cmpa () 
{ 
    local -n _a=$1;
    local -n _b=$2;
    [[ ${#_a[@]} -ne ${#_b[@]} ]] && return 1;
    for ((i=0; i<${#_a[@]}; i++))
    do
        [[ "${_a[i]}" != "${_b[i]}" ]] && return 1;
    done;
    return 0
}
pa:cmpaa () 
{ 
    local -n _a=$1;
    local -n _b=$2;
    [[ ${#_a[@]} -ne ${#_b[@]} ]] && return 1;
    for k in "${!_a[@]}";
    do
        [[ -v _b[$k] ]] || return 1;
        [[ "${_a[$k]}" != "${_b[$k]}" ]] && return 1;
    done;
    return 0
}
