pa:parsarg () 
{ 
    shopt -q extglob || { 
        shopt -s extglob;
        trap 'shopt -u extglob' RETURN
    };
    local -a tmp;
    local opt next ctx;
    local state=START;
    local END='@(-[!0-9]*|)';
    local ARG='!(++)';
    local VAL='@(-|[!-]*|-[0-9]*)';
    local NUM='-[0-9]*';
    local ANY='*';
