    local LONG='--*';
    local ASSIGN='@(--*=*|-[!0-9]*=*)';
    until [[ $# -eq 0 ]]; do
        [[ -n "$debug" ]] && echo $# "$@";
        if [[ "$2" == $END ]]; then
            next=END;
        else
            if [[ "$2" == $VAL ]]; then
                next=VAL;
            else
                next=ERROR;
            fi;
        fi;
        ctx="$state^$1^$next";
        [[ -n "$debug" ]] && echo "$ctx";
        if [[ "$ctx" == $ANY^$ANY^ERROR ]]; then
            do=ERROR;
        else
            if [[ "$ctx" == $ANY^$CONT^$ANY ]]; then
                do=CONT;
            else
                if [[ "$ctx" == $ANY^$ARGS^$ANY ]]; then
                    do=NEXT state=ARGS;
                else
                    if [[ "$ctx" == START^@($VAL|$NUM)^$ANY ]]; then
                        do=ARG;
                    else
                        if [[ "$ctx" == ARGS^$ARG^$ANY ]]; then
                            do=ARG;
                        else
                            if [[ "$ctx" == @(START|OPT)^$ASSIGN^$ANY ]]; then
                                do=ASSIGN state=START;
                            else
                                if [[ "$ctx" == @(START|OPT)^$SHORT^$ANY ]]; then
                                    do=SHORT state=START;
                                else
                                    if [[ "$ctx" == START^$LONG^END ]]; then
                                        do=LONG-END;
                                    else
                                        if [[ "$ctx" == START^$LONG^VAL ]]; then
                                            do=LONG-VAL state=OPT;
                                        else
                                            if [[ "$ctx" == OPT^$ANY^VAL ]]; then
                                                do=OPT-VAL;
                                            else
                                                if [[ "$ctx" == OPT^$ANY^END ]]; then
                                                    do=OPT-VAL state=START;
                                                else
                                                    do=ERROR;
                                                fi;
                                            fi;
                                        fi;
                                    fi;
                                fi;
                            fi;
                        fi;
                    fi;
                fi;
            fi;
        fi;
        case $do in 
            "")
                :
            ;;
            CONT)
                shift;
                cont=("$@");
                shift $#
            ;;
            NEXT)
                shift
            ;;
            ARG)
                args+=("$1");
                shift
            ;;
            SHORT)
                tmp=();
                opt="${1:1}";
                shift;
                for ((i=0; i < ${#opt}; i++))
