                opt="${1%%=*}";
                val="${1#*=}";
                opt="${opt##+(-)}";
                opts["$opt"]="$val";
                shift
            ;;
            LONG-END)
                opt="${1:2}";
                opts["$opt"]=$((opts["$opt"] + 1));
                shift
            ;;
            LONG-VAL)
                opt="${1:2}";
                opts["$opt"]="$2";
                shift 2
            ;;
            OPT-VAL)
                opts["$opt"]+=" $1";
                shift
            ;;
            ERROR | *)
                { 
                    echo $# "$@";
                    declare -p do state next
                } | fmt -999;
                shift
            ;;
        esac;
        [[ -n "$debug" ]] && declare -p opts args cont;
    done
